 # generate multisets of component pairs summing n, min<=max and allow (0,1) only for isolated
 res=[]
 def rec(rem, start, cur):
  if rem==0: res.append(tuple(cur)); return
  pairs=[]
  for a in range(0,rem+1):
   for b in range(max(a,1),rem+1):
    if a+b==0 or a+b>rem: continue
    if a==0 and b!=1: continue
    pairs.append((a,b))
  pairs=sorted(pairs)
  for pair in pairs:
   if pair<start: continue
   cur.append(pair); rec(rem-sum(pair), pair, cur); cur.pop()
 rec(n,(0,0),[])
 return res
