import sys
from collections import deque

def merge_grundy(isolated, odd_nonisolated, even_odd_parts):
    q = even_odd_parts & 1

    if odd_nonisolated >= 3:
        return q
    if odd_nonisolated == 2:
        return 2 + q if isolated % 2 == 0 else q
    if odd_nonisolated == 1:
        return 2 + q if isolated % 2 == 1 else q

    r = isolated & 3
    if r == 2:
        return 1
    if r == 0:
        return 0
    return q

def main():
    input = sys.stdin.readline
    N, M = map(int, input().split())

    adj = [[] for _ in range(N)]
    for _ in range(M):
        u, v = map(int, input().split())
        u -= 1
        v -= 1
        adj[u].append(v)
        adj[v].append(u)

    color = [-1] * N
    isolated = 0
    odd_nonisolated = 0
    even_odd_parts = 0
    internal_parity = 0

    for s in range(N):
        if color[s] != -1:
            continue

        color[s] = 0
        q = deque([s])
        cnt = [0, 0]
        deg_sum = 0

        while q:
            v = q.popleft()
            cnt[color[v]] += 1
            deg_sum += len(adj[v])

            for to in adj[v]:
                if color[to] == -1:
                    color[to] = color[v] ^ 1
                    q.append(to)

        edges = deg_sum // 2
        a, b = cnt
        size = a + b

        internal_parity ^= (a * b - edges) & 1

        if size == 1:
            isolated += 1
        elif size & 1:
            odd_nonisolated += 1
        elif (a & 1) and (b & 1):
            even_odd_parts += 1

    grundy = merge_grundy(isolated, odd_nonisolated, even_odd_parts)
    print("Aoki" if (grundy ^ internal_parity) != 0 else "Takahashi")

if __name__ == "__main__":
    main()
